const stickyBar = () => `    <div class="sticky-cta" aria-hidden="true">
      <a class="button" href="/download/" data-event="download_cta_clicked" data-event-source="sticky_bar">Start Free →</a>
      <button class="sticky-cta-dismiss" type="button" aria-label="Dismiss">✕</button>
    </div>`;

function page(def) {
  const schemas = [ORG_SCHEMA, breadcrumb([['Home', '/'], ...(def.crumbs || [[def.crumbName, def.url]])])];
  if (def.faq) schemas.push(faqSchema(def.faq));
  if (def.extraSchema) schemas.push(...def.extraSchema);
  const schemaTags = schemas.map(s => `    <script type="application/ld+json">\n${JSON.stringify(s, null, 2).replace(/^/gm, '      ')}\n    </script>`).join('\n');
  const bodyAttrs = def.bodyAttrs ? ' ' + def.bodyAttrs : '';
  const crumbTrail = (def.crumbs || [[def.crumbName, def.url]]);
  const crumbHtml = `<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a>${crumbTrail.map((c, i) =>
    i === crumbTrail.length - 1 ? ` › <span aria-current="page">${c[0]}</span>` : ` › <a href="${c[1]}/">${c[0]}</a>`).join('')}</nav>`;

  return `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${def.title}</title>
    <meta name="description" content="${def.desc}" />
    <meta name="theme-color" content="#1f7f4d" />
    <meta property="og:title" content="${def.title}" />
    <meta property="og:description" content="${def.desc}" />
    <meta property="og:type" content="website" />
    <meta property="og:url" content="https://kitabu.ai${def.url}" />
    <meta property="og:image" content="https://kitabu.ai/assets/kitabu-hero-family-optimized.jpg" />
    <link rel="canonical" href="https://kitabu.ai${def.url}" />
    <link rel="icon" href="/assets/kitabu-favicon-bold.ico" sizes="any" />
    <link rel="icon" type="image/png" sizes="32x32" href="/assets/kitabu-favicon-bold-32.png" />
    <link rel="apple-touch-icon" sizes="180x180" href="/assets/kitabu-touch-icon-bold.png" />
    <link rel="preload" href="/assets/fonts/bricolage-grotesque-latin.woff2" as="font" type="font/woff2" crossorigin />
    <link rel="preload" href="/assets/fonts/plus-jakarta-sans-latin.woff2" as="font" type="font/woff2" crossorigin />
    <link rel="stylesheet" href="${ASSET_CSS}" />
    <script>document.documentElement.classList.add('js');</script>
${schemaTags}
  </head>
  <body${bodyAttrs}>
${header()}
    <main>
      <section class="page-hero">
        <div class="container">
          ${crumbHtml}
          <p class="eyebrow" data-reveal>${def.kicker}</p>
          <h1 data-split>${def.h1}</h1>
          <p class="hero-lede" data-reveal>${def.lede}</p>
${def.heroExtra || ''}
        </div>
      </section>
${def.content}
    </main>
${footer()}
${def.noSticky ? '' : stickyBar()}
    <script src="${ASSET_CONFIG}" defer></script>
    <script src="${ASSET_JS}" defer></script>
    <script src="${ASSET_LEGACY_JS}" defer></script>
  </body>
</html>
`;
}

function article(def) {
  const schemas = [ORG_SCHEMA,
    breadcrumb([['Home', '/'], ['Learning guide', '/#blog'], [def.crumbName, def.url]]),
    {
      '@context': 'https://schema.org',
      '@type': 'Article',
      headline: def.h1.replace(/<[^>]+>/g, ''),
      description: def.desc,
      image: 'https://kitabu.ai' + (def.image || '/assets/kitabu-hero-family-optimized.jpg'),
      datePublished: def.published,
      dateModified: '2026-07-04',
      author: { '@type': 'Organization', name: 'Kitabu AI' },
      publisher: { '@type': 'Organization', name: 'Kitabu AI', logo: { '@type': 'ImageObject', url: 'https://kitabu.ai/assets/kitabu-icon-bold-512.png' } },
      mainEntityOfPage: 'https://kitabu.ai' + def.url
    }];
  if (def.faq) schemas.push(faqSchema(def.faq));
  const schemaTags = schemas.map(s => `    <script type="application/ld+json">\n${JSON.stringify(s, null, 2).replace(/^/gm, '      ')}\n    </script>`).join('\n');
  return `<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>${def.title}</title>
    <meta name="description" content="${def.desc}" />
    <meta name="theme-color" content="#1f7f4d" />
    <meta property="og:title" content="${def.title}" />
    <meta property="og:description" content="${def.desc}" />
    <meta property="og:type" content="article" />
    <meta property="og:url" content="https://kitabu.ai${def.url}" />
    <meta property="og:image" content="https://kitabu.ai${def.image || '/assets/kitabu-hero-family-optimized.jpg'}" />
    <meta property="article:published_time" content="${def.published}" />
    <meta property="article:modified_time" content="2026-07-04" />
    <link rel="canonical" href="https://kitabu.ai${def.url}" />
    <link rel="icon" href="/assets/kitabu-favicon-bold.ico" sizes="any" />
    <link rel="icon" type="image/png" sizes="32x32" href="/assets/kitabu-favicon-bold-32.png" />
    <link rel="stylesheet" href="${ASSET_CSS}" />
    <script>document.documentElement.classList.add('js');</script>
${schemaTags}
  </head>
  <body>
${header()}
    <main>
      <section class="page-hero">
        <div class="container prose" style="margin-inline:auto">
          <a class="article-back" href="/#blog">← Back to the learning guide</a>
          <p class="eyebrow">${def.kicker}</p>
          <h1>${def.h1}</h1>
          <p class="article-meta">Kitabu AI team · Updated 4 July 2026</p>
          <p class="hero-lede">${def.lede}</p>
        </div>
      </section>
      <section class="section" style="padding-top: 24px">
        <div class="container prose" style="margin-inline:auto">
${def.body}
        </div>
      </section>
${def.faq ? `      <section class="section" style="padding-top: 0">
        <div class="container prose" style="margin-inline:auto">
          <h2>Common questions</h2>${faqHtml(def.faq)}
        </div>
      </section>
` : ''}    </main>
${footer()}
    <script src="${ASSET_CONFIG}" defer></script>
    <script src="${ASSET_JS}" defer></script>
    <script src="${ASSET_LEGACY_JS}" defer></script>
  </body>
</html>
`;
}

