/* =====================================================================
   BLOGS — every post lives in apps/web/build/articles/*.mjs (one module
   per post; each default-exports an array of article definitions). Add
   new posts there, not here, so the content engine can grow to weekly
   publishing without bloating this file. Content rules: see
   growth-machine/seo-content-strategy.md at the repo root.
   ===================================================================== */
const articles = [];
const ARTICLES_DIR = join(dirname(fileURLToPath(import.meta.url)), 'articles');
if (existsSync(ARTICLES_DIR)) {
  for (const f of readdirSync(ARTICLES_DIR).filter(n => n.endsWith('.mjs')).sort()) {
    const mod = await import(pathToFileURL(join(ARTICLES_DIR, f)).href);
    articles.push(...mod.default);
  }
}
{
  const seen = new Set();
  for (const a of articles) {
    if (seen.has(a.url)) throw new Error(`Duplicate article url: ${a.url}`);
    seen.add(a.url);
  }
}

/* =====================================================================
   SITEMAP
   ===================================================================== */
function sitemap() {
  const urls = [
    { loc: 'https://kitabu.ai/', priority: '1.0' },
    ...pages.map(p => ({ loc: 'https://kitabu.ai' + p.url, priority: p.url === '/schools/demo' || p.url === '/pricing' || p.url === '/download' ? '0.9' : '0.8' })),
    ...articles.map(a => ({ loc: 'https://kitabu.ai' + a.url, priority: '0.7' })),
    { loc: 'https://app.kitabu.ai/terms', priority: '0.4' },
    { loc: 'https://app.kitabu.ai/policy', priority: '0.4' },
    { loc: 'https://app.kitabu.ai/privacy', priority: '0.4' },
    { loc: 'https://app.kitabu.ai/deletion', priority: '0.4' }
  ];
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.map(u =>
    `  <url>\n    <loc>${u.loc}</loc>\n    <lastmod>2026-07-04</lastmod>\n    <priority>${u.priority}</priority>\n  </url>`).join('\n')}\n</urlset>\n`;
}

/* =====================================================================
   WRITE EVERYTHING
   ===================================================================== */
let written = 0;
let unchanged = 0;
function writeIfChanged(out, content) {
  mkdirSync(dirname(out), { recursive: true });
  if (existsSync(out) && readFileSync(out, 'utf8') === content) {
    unchanged++;
    return;
  }
  writeFileSync(out, content, 'utf8');
  written++;
}

for (const def of pages) writeIfChanged(join(WEB, def.path), page(def));
for (const def of articles) writeIfChanged(join(WEB, def.path), article(def));
writeIfChanged(join(WEB, '404.html'), notFound);
writeIfChanged(join(WEB, 'sitemap.xml'), sitemap());
console.log(`Wrote ${written} file(s), ${unchanged} unchanged, under ${WEB}`);
